using System.Globalization;
using System.Windows.Controls;

namespace Timesheet;

public sealed class HoursValidationRule : ValidationRule
{
    public override ValidationResult Validate(object value, CultureInfo cultureInfo)
    {
        if (value is string text &&
            double.TryParse(text, NumberStyles.Float, cultureInfo, out double hours) &&
            double.IsFinite(hours) && hours >= 0 && hours <= 24)
        {
            return ValidationResult.ValidResult;
        }

        return new ValidationResult(false,
            $"Enter hours from 0 to 24 using '{cultureInfo.NumberFormat.NumberDecimalSeparator}' as the decimal separator (no thousands separators).");
    }
}

